def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")

    def step_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x != sx:
            dx = 1 if target_x > sx else -1
        if target_y != sy:
            dy = 1 if target_y > sy else -1
        return [dx, dy]

    # Handle Pursuit-Evasion environment
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_towards(ox, oy)
        corners = [
            [0, 0],
            [0, observation.get("grid_height", 1) - 1),
            [observation.get("grid_width", 1) - 1, 0],
            [observation.get("grid_width", 1) - 1, observation.get("grid_height", 1) - 1),
        ]
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return step_towards(target[0], target[1])

    # Handle Territory Control environment
    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if targets:
            target = min(targets, key=lambda t: abs(t[0] - sx) + abs(t[1] - sy))
            return step_towards(target[0], target[1])
        else:
            return [0, 0]

    # Resource Collection environment
    resources = observation.get("resources") or []
    if resources:
        target = min(resources, key=lambda r: abs(r[0] - sx) + abs(r[1] - sy))
        return step_towards(target[0], target[1])
    else:
        return [0, 0]

